    (SUM(?holdingValue) AS ?totalHoldingValue)
    (SUM(?sectorInvestment) AS ?totalSectorAllocation)
    (SUM(?cashFlowAmount) AS ?totalCashFlowAmount)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?categoryRaw, "NULL") AS ?category)
            (SUM(xsd:decimal(?currentValue)) AS ?holdingValue)
            (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestment)
            (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:category ?categoryRaw .

            OPTIONAL {
