                ?cashFlow rdf:type wm:CashFlow ;
                          wm:cashFlowOfInvestor ?investor ;
                          wm:amount ?amount .
            }
        }
        GROUP BY ?investorId ?categoryRaw
    }
}
GROUP BY ?category

