SELECT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .

    FILTER (
        EXISTS {
            SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
            WHERE {
                ?investor wm:hasInvestmentGoal ?goal .
                ?goal wm:shortfall ?shortfallRaw .
                BIND(xsd:decimal(?shortfallRaw) AS ?shortfall)
                FILTER(xsd:decimal(?shortfallRaw) > 0)
            }
            GROUP BY ?investor
            HAVING (SUM(xsd:decimal(?shortfall)) > 0)
        }
    )

    FILTER (
        EXISTS {
            SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
            WHERE {
                ?investor wm:hasCashFlow ?cashFlow .
                ?cashFlow wm:amount ?amountRaw .
                BIND(xsd:decimal(?amountRaw) AS ?amount)
            }
            GROUP BY ?investor
            HAVING (SUM(xsd:decimal(?amount)) < 0)
        }
    )

    FILTER (
        EXISTS {
            ?investor wm:hasRebalancingAction ?rebalancing .
            ?rebalancing wm:action ?action .
            FILTER(LCASE(STR(?action)) = "de-risking")
        }
    )
}

