PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio)
                     (AVG(xsd:decimal(?volatility)) AS ?avgVolatilityPct)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?goal .
      ?goal rdf:type wm:InvestmentGoal ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?volatility .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?sharpe)) < 0 && AVG(xsd:decimal(?volatility)) > 10)
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?holdingGain)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding ;
               wm:currentValue ?currentValue ;
               wm:cost ?cost .
      BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?gain)) < 0)
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow rdf:type wm:CashFlow ;
                wm:amount ?amount .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?amount)) < 1000000)
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

