               wm:holdingId ?holdingId ;
               wm:hasSector ?sectorNode .
      ?sectorNode a wm:Sector ;
                  rdfs:label ?sector_label .

      ?holding wm:hasInvestmentType ?investmentTypeNode .
      ?investmentTypeNode a wm:InvestmentType .

      ?holding wm:hasSegment ?segmentNode .
      ?segmentNode a wm:Segment .

      ?holding wm:hasCategory ?categoryNode .
      ?categoryNode a wm:Category .
    }
  }
}
