SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow2025)
WHERE {
  {
    SELECT ?cashFlow (SAMPLE(?investorIdRaw) AS ?investorId) ?amount
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:date ?date ;
                wm:amount ?amount ;
                wm:cashFlowOfInvestor ?investor .
      ?investor wm:investorId ?investorIdRaw .
