PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
(SUM(COALESCE(xsd:decimal(?netCashFlow), 0)) +
 SUM(COALESCE(xsd:decimal(?rebalancingAmount), 0)) +
 SUM(COALESCE(xsd:decimal(?allocationChange), 0)) AS ?score)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:hasCashFlow ?cashFlow .
        ?cashFlow wm:amount ?cashFlowAmount .
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?rebalanceAmount)) AS ?rebalancingAmount)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:hasRebalancingAction ?rebalancingAction .
        ?rebalancingAction wm:amount ?rebalanceAmount .
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(?allocationChangeRaw) AS ?allocationChange)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
        ?scenarioRebalancing wm:currentAllocationPct ?currentPct ;
                            wm:newAllocationPct ?newPct .
        BIND((xsd:decimal(?newPct) - xsd:decimal(?currentPct)) AS ?allocationChangeRaw)
      }
    }
    GROUP BY ?investorId
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?score) LIMIT 10

