SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasRebalancingAction ?rebalance .

  ?cashFlow rdf:type wm:CashFlow ;
            wm:type ?cashFlowType .

  FILTER(LCASE(STR(?cashFlowType)) = "sip") .

  ?goal rdf:type wm:InvestmentGoal ;
        wm:investmentGoal ?goalType .

  FILTER(LCASE(STR(?goalType)) = "growth") .

  ?rebalance rdf:type wm:RebalancingAction ;
             wm:logic ?rebalanceLogic .

  FILTER(CONTAINS(LCASE(STR(?rebalanceLogic)), "momentum")) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName WHERE {
    {
        SELECT ?investor ?investorId ?investorName (AVG(xsd:decimal(?avgVolatilityPctRaw)) AS ?avgVolatilityPct) (AVG(xsd:decimal(?diversificationScoreRaw)) AS ?diversificationScore) WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:investorName ?investorName ;
                      wm:hasInvestmentGoal ?goal ;
                      wm:hasPortfolioHealth ?health .
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:avgVolatilityPct ?avgVolatilityPctRaw .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:diversificationScore ?diversificationScoreRaw .
        }
        GROUP BY ?investor ?investorId ?investorName
    }
    FILTER(?avgVolatilityPct > 30 && ?diversificationScore < 30)
}

