           wm:heldByInvestor ?investor .
  FILTER NOT EXISTS {
    ?holding wm:hasSector ?sector .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?month
    (SUM(?preDeposit) AS ?DepositTotal)
    (SUM(?preWithdrawal) AS ?WithdrawalTotal)
WHERE {
    {
        SELECT
            ?date
            (SUM(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?amount), 0)) AS ?preDeposit)
            (SUM(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?amount), 0)) AS ?preWithdrawal)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:date ?date ;
                      wm:type ?type ;
                      wm:amount ?amount .
            FILTER(STRSTARTS(STR(?date), "2025"))
        }
        GROUP BY ?date
    }
    BIND(SUBSTR(STR(?date), 1, 7) AS ?month)
}
GROUP BY ?month
ORDER BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
WHERE {
    {
        SELECT ?investorId
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:riskTolerance "Aggressive" ;
                      wm:hasInvestmentGoal ?goal .
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:shortfall ?shortfallRaw ;
                  wm:currentValue ?currentValueRaw ;
                  wm:targetAmount ?targetAmountRaw .
            BIND(xsd:decimal(?shortfallRaw) AS ?shortfall)
            BIND(xsd:decimal(?currentValueRaw) AS ?currentValue)
            BIND(xsd:decimal(?targetAmountRaw) AS ?targetAmount)
            FILTER(?shortfall > 0 || ?currentValue < ?targetAmount)
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasPortfolioHealth ?health .
            ?health rdf:type wm:PortfolioHealth ;
                    wm:goalMatchPct ?goalMatchPctRaw .
            BIND(xsd:decimal(?goalMatchPctRaw) AS ?goalMatchPct)
            FILTER(?goalMatchPct < 100)
        }
        GROUP BY ?investorId
    }

    {
        SELECT ?investorId
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasHolding ?holding .
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:returnsPct ?returnsPctRaw .
            BIND(xsd:decimal(?returnsPctRaw) AS ?returnsPct)
            FILTER(?returnsPct < 0)
        }
        GROUP BY ?investorId
    }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (MIN(xsd:decimal(?liquidityScoreRaw)) AS ?liquidityScore)
WHERE {
  {
    SELECT ?investor ?investorId
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:category "Debt" ;
                wm:hasPortfolioHealth ?health .
      ?health wm:liquidityScore ?liquidityScoreRaw .
      FILTER(xsd:decimal(?liquidityScoreRaw) < 40)

      {
        ?holding rdf:type wm:PortfolioHolding ;
                 wm:sector "Healthcare" ;
                 wm:heldByInvestor ?investor .
      }
      UNION
      {
        ?allocation rdf:type wm:SectorAllocation ;
                    wm:sector "Healthcare" ;
                    wm:allocationOfInvestor ?investor .
      }
    }
    GROUP BY ?investor ?investorId
  }

  ?investor wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY ?investorId

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (SAMPLE(?investorNameRaw) AS ?investorName)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorNameRaw .

      {
        SELECT ?investor
        WHERE {
          ?rebalancingAction rdf:type wm:RebalancingAction ;
                             wm:rebalancingActionOfInvestor ?investor ;
                             wm:action "Sell" .
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor
        WHERE {
          ?holding rdf:type wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:returnsPct ?returnsPctRaw .
          FILTER(xsd:decimal(?returnsPctRaw) < 0)
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor
        WHERE {
          ?portfolioHealth rdf:type wm:PortfolioHealth ;
                           wm:healthOfInvestor ?investor ;
                           wm:diversificationScore ?diversificationScoreRaw .
          FILTER(xsd:decimal(?diversificationScoreRaw) < 30)
        }
        GROUP BY ?investor
      }

      {
        SELECT ?investor
        WHERE {
          ?sectorAllocation rdf:type wm:SectorAllocation ;
                            wm:allocationOfInvestor ?investor ;
                            wm:allocationPct ?allocationPctRaw .
          FILTER(xsd:decimal(?allocationPctRaw) > 35)
        }
        GROUP BY ?investor
      }
    }
    GROUP BY ?investor ?investorId
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    (SUM(xsd:decimal(?netAmount)) AS ?totalNetAmount)
    (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
WHERE {
    {
        SELECT
            ?investorId
            (SUM(xsd:decimal(?amount)) AS ?netAmount)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    {
        SELECT
            ?investorId
            (AVG(xsd:decimal(?progressPctRaw)) AS ?progressPct)
            (SUM(xsd:decimal(?shortfallRaw)) AS ?shortfall)
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:progressPct ?progressPctRaw ;
                  wm:shortfall ?shortfallRaw .
            ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
    }
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:riskTolerance ?riskToleranceRaw .
    BIND(LCASE(STR(?riskToleranceRaw)) AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?category
    (SUM(?depositAmount) AS ?totalDeposit)
    (SUM(?withdrawalAmount) AS ?totalWithdrawal)
WHERE {
    {
        SELECT
            ?investor
            (COALESCE(?categoryRaw, "NULL") AS ?category)
            (SUM(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?amount), 0)) AS ?depositAmount)
            (SUM(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?amount), 0)) AS ?withdrawalAmount)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:type ?type ;
                      wm:amount ?amount .

            OPTIONAL {
                ?investor wm:hasCategory ?categoryObj .
                ?categoryObj rdfs:label ?categoryRaw .
            }
        }
        GROUP BY ?investor ?categoryRaw
    }
}
GROUP BY ?category

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    ?investmentGoal
    (SUM(?goalCountPerInvestor) AS ?goalCount)
WHERE {
    {
        SELECT
            ?investorId
            ?riskTolerance
            ?investmentGoal
            (COUNT(DISTINCT ?goalId) AS ?goalCountPerInvestor)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:riskTolerance ?riskToleranceRaw .
            BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)

            ?goal rdf:type wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:investmentGoal ?investmentGoalRaw ;
                  wm:goalId ?goalId .
            BIND(COALESCE(?investmentGoalRaw, "NULL") AS ?investmentGoal)
        }
        GROUP BY ?investorId ?riskTolerance ?investmentGoal
    }
}
GROUP BY ?riskTolerance ?investmentGoal

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?holding ?holdingId ?investmentName
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentName ?investmentName . }

  FILTER EXISTS {
    ?holding wm:hasSector ?sector .
    ?holding wm:hasCategory ?category .
    ?holding wm:hasSegment ?segment .
    ?holding wm:hasInvestmentType ?investmentType .
  }

  FILTER NOT EXISTS {
    ?holding wm:returnsPct ?returnsPct .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasHolding ?holding .
            ?holding wm:currentValue ?currentValue .
        }
        GROUP BY ?investor
    }
    FILTER(?totalCurrentValue = 0) .

    ?investor wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:hasPortfolioHealth ?health ;
              wm:hasSectorAllocation ?allocation .

    ?health wm:liquidityScore ?liquidityScore .
    FILTER(xsd:decimal(?liquidityScore) < 30) .

    ?allocation wm:allocationPct ?allocationPct .
    FILTER(xsd:decimal(?allocationPct) > 30) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
WHERE {
    ?investor a wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:hasHolding ?holding .

    ?holding a wm:PortfolioHolding ;
             wm:currentValue ?currentValue ;
             wm:cost ?cost .

    BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?holdingGain)
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalHoldingGain) DESC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .

    # Withdrawal cash flows
    ?cashFlow rdf:type wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:type "Withdrawal" .

    # Negative-return holdings
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:returnsPct ?returnsPctRaw .
    BIND(xsd:decimal(?returnsPctRaw) AS ?returnsPct)
    FILTER(?returnsPct < 0)

    # Allocation_pct above 30
    ?allocation rdf:type wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:allocationPct ?allocationPctRaw .
    BIND(xsd:decimal(?allocationPctRaw) AS ?allocationPct)
    FILTER(?allocationPct > 30)

    # Liquidity_score below 30
    ?health rdf:type wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:liquidityScore ?liquidityScoreRaw .
    BIND(xsd:decimal(?liquidityScoreRaw) AS ?liquidityScore)
    FILTER(?liquidityScore < 30)
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskToleranceLabel
    (COALESCE(?goalLabel, "NULL") AS ?investmentGoalLabel)
    (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
    {
        SELECT DISTINCT ?investorId ?riskToleranceLabel ?goalLabel
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasRiskTolerance ?riskTolerance .
            ?riskTolerance rdfs:label ?riskToleranceLabel .

            OPTIONAL {
                ?investor wm:hasInvestmentGoal ?goal .
                ?goal rdf:type wm:InvestmentGoal ;
                      rdfs:label ?goalLabel .
            }

            FILTER (
                EXISTS {
                    ?holding rdf:type wm:PortfolioHolding ;
                             wm:heldByInvestor ?investor .
                }
            )
            FILTER (
                EXISTS {
                    ?allocation wm:heldByInvestor ?investor .
                }
            )
            FILTER (
                EXISTS {
                    ?cashFlow rdf:type wm:CashFlow ;
                              wm:cashFlowOfInvestor ?investor .
                }
            )
        }
    }
}
GROUP BY ?riskToleranceLabel ?goalLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceGroup
       (AVG(?innerAvgGoalShortfall) AS ?avgGoalShortfall)
       (AVG(?innerAvgPortfolioHealthScore) AS ?avgPortfolioHealthScore)
WHERE {
  {
    SELECT ?investor
           ?riskToleranceValue
           (AVG(xsd:decimal(?shortfall)) AS ?innerAvgGoalShortfall)
           (AVG(?healthScore) AS ?innerAvgPortfolioHealthScore)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:hasRiskTolerance ?riskTolerance ;
                wm:hasInvestmentGoal ?goal ;
                wm:hasPortfolioHealth ?health .
      ?riskTolerance wm:riskTolerance ?riskToleranceValue .
      ?goal wm:shortfall ?shortfall .
      ?health wm:goalMatchPct ?goalMatch ;
              wm:diversificationScore ?diversity ;
              wm:liquidityScore ?liquidity ;
              wm:riskScore ?risk .
      BIND((xsd:decimal(?goalMatch) + xsd:decimal(?diversity) + xsd:decimal(?liquidity) + xsd:decimal(?risk)) / 4 AS ?healthScore)
    }
    GROUP BY ?investor ?riskToleranceValue
  }
  BIND(?riskToleranceValue AS ?riskToleranceGroup)
}
GROUP BY ?riskToleranceGroup

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskToleranceLabel
    (AVG(xsd:decimal(?avgProgressPct)) AS ?avgGoalProgress)
    (AVG(xsd:decimal(?avgVolatility)) AS ?avgPortfolioRisk)
WHERE {
    {
        SELECT
            ?investor
            (COALESCE(?riskToleranceLabelRaw, "NULL") AS ?riskToleranceLabel)
            (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
            (AVG(xsd:decimal(?volatilityPct)) AS ?avgVolatility)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:hasRiskTolerance ?riskTolerance .

            OPTIONAL {
                ?riskTolerance rdfs:label ?riskToleranceLabelRaw .
            }

            ?investor wm:hasInvestmentGoal ?goal .
            ?goal wm:progressPct ?progressPct ;
                  wm:avgVolatilityPct ?volatilityPct .
        }
        GROUP BY ?investor ?riskToleranceLabelRaw
    }
}
GROUP BY ?riskToleranceLabel

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalHoldingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue ;
               wm:cost ?cost .
    }
    GROUP BY ?investor
  }
  FILTER(?totalHoldingGain < 0)

  {
    SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?totalGoalShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }
  FILTER(?totalGoalShortfall > 0)

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  FILTER(?totalNetCashFlow < 0)

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId .

    ?cashFlow rdf:type wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:type "Withdrawal" .

    ?goal rdf:type wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:timeToGoalMonths ?timeToGoalMonthsRaw .
    FILTER(xsd:decimal(?timeToGoalMonthsRaw) <= 12)

    ?action rdf:type wm:RebalancingAction ;
            wm:rebalancingActionOfInvestor ?investor ;
            wm:action "Sell" .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?investorName WHERE {
    ?investor rdf:type wm:Investor ;
              wm:riskTolerance "Aggressive" ;
              wm:investorName ?investorName ;
              wm:hasInvestmentGoal ?goal ;
              wm:hasHolding ?goldHolding .

    ?goal rdf:type wm:InvestmentGoal ;
          wm:shortfall ?shortfallRaw ;
          wm:belongsToInvestor ?investor .
    FILTER(xsd:decimal(?shortfallRaw) > 0) .

    ?goldHolding rdf:type wm:PortfolioHolding ;
                 wm:investmentType "Gold" ;
                 wm:heldByInvestor ?investor .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPctRaw)) AS ?progressPct)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:progressPct ?progressPctRaw ;
            wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId ;
            wm:hasSegment ?segmentObj .
  ?segmentObj rdfs:label ?segment .
}
GROUP BY ?segment

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
