PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowTypeLabel (COUNT(DISTINCT ?cashFlow) AS ?transactionCount) (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
  {
    SELECT ?cashFlowType (SAMPLE(?label) AS ?cashFlowTypeLabel)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:hasCashFlowType ?cashFlowType ;
                wm:amount ?amount .
      ?cashFlowType rdf:type wm:CashFlowType ;
                    rdfs:label ?label .
    }
    GROUP BY ?cashFlowType
  }
  ?cashFlow rdf:type wm:CashFlow ;
            wm:hasCashFlowType ?cashFlowType ;
            wm:amount ?amount .
}
GROUP BY ?cashFlowType ?cashFlowTypeLabel

PREFIX schema1: <http://schema.org/>

