    ?cashFlowType rdfs:label ?cashFlowTypeLabel .
    FILTER(LCASE(STR(?cashFlowTypeLabel)) = "withdrawal") .

    ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                         wm:hasMarketScenario ?marketScenario .
    ?marketScenario rdfs:label ?marketScenarioLabel .
    FILTER(LCASE(STR(?marketScenarioLabel)) = "bear market") .
}

