PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investorId ?category ?riskScore
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:category ?category ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth rdf:type wm:PortfolioHealth ;
                       wm:riskScore ?riskScore .
    }
