PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentGoal (AVG(?investorAvgProgress) AS ?avgProgress)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?investorAvgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPctRaw .
      ?investor rdf:type wm:Investor ;
                wm:riskTolerance ?riskToleranceRaw ;
                wm:investorId ?investorId .
      BIND(LCASE(STR(?riskToleranceRaw)) AS ?riskTolerance)
      FILTER(CONTAINS(?riskTolerance, "aggressive"))
      BIND(xsd:decimal(?progressPctRaw) AS ?progressPct)
    }
    GROUP BY ?investorId
  }
  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:investmentGoal ?investmentGoal .
}
GROUP BY ?investmentGoal
ORDER BY DESC(?avgProgress) ASC(?investmentGoal)
LIMIT 5

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    {
        SELECT ?investor
               (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
               (AVG(xsd:decimal(?riskScore)) AS ?avgRisk)
               (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidity)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:hasInvestmentGoal ?goal ;
                      wm:hasPortfolioHealth ?health .

            ?goal rdf:type wm:InvestmentGoal ;
                  wm:progressPct ?progressPct .

            ?health rdf:type wm:PortfolioHealth ;
                    wm:riskScore ?riskScore ;
                    wm:liquidityScore ?liquidityScore .
        }
        GROUP BY ?investor ?investorId
        HAVING (AVG(xsd:decimal(?progressPct)) < 20 &&
                AVG(xsd:decimal(?riskScore)) < 30 &&
                AVG(xsd:decimal(?liquidityScore)) < 30)
    }

    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
