PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor (SAMPLE(?investorIdRaw) AS ?investorId)
    WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:date ?date ;
                wm:cashFlowOfInvestor ?investor .
      FILTER(?date >= "2025-01-01"^^xsd:date && ?date < "2026-01-01"^^xsd:date)
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorIdRaw .
    }
    GROUP BY ?investor
  }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    (SUM(?depositAmount) AS ?totalDepositAmount)
    (SUM(?rebalancingAmount) AS ?totalRebalancingAmount)
WHERE {
    {
        SELECT
            ?investor
            ?riskTolerance
            (COALESCE(SUM(xsd:decimal(?depositAmountRaw)), 0) AS ?depositAmount)
            (COALESCE(SUM(xsd:decimal(?rebalancingAmountRaw)), 0) AS ?rebalancingAmount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:riskTolerance ?riskTolerance .
            OPTIONAL {
                ?investor wm:hasCashFlow ?cashFlow .
                ?cashFlow rdf:type wm:CashFlow ;
                          wm:type "Deposit" ;
                          wm:amount ?depositAmountRaw .
            }
            OPTIONAL {
                ?investor wm:hasRebalancingAction ?rebalancingAction .
                ?rebalancingAction rdf:type wm:RebalancingAction ;
                                   wm:amount ?rebalancingAmountRaw .
            }
        }
        GROUP BY ?investor ?riskTolerance
    }
}
GROUP BY ?riskTolerance

