PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  ?logic
  ?triggeredAction
  (COUNT(DISTINCT ?investorId) AS ?distinctInvestorCount)
WHERE {
  {
    SELECT ?investor ?logic ?triggeredAction ?investorId
    WHERE {
      ?action rdf:type wm:RebalancingAction ;
              wm:rebalancingActionOfInvestor ?investor ;
              wm:logic ?logicRaw .
      ?scenario rdf:type wm:ScenarioRebalancing ;
                wm:scenarioRebalancingOfInvestor ?investor ;
                wm:triggeredAction ?triggeredActionRaw .
      ?investor wm:investorId ?investorId .
      BIND(COALESCE(STR(?logicRaw), "NULL") AS ?logic)
      BIND(COALESCE(STR(?triggeredActionRaw), "NULL") AS ?triggeredAction)
    }
  }
}
GROUP BY ?logic ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    ?sector
    (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
    {
        SELECT ?investorId ?riskTolerance ?sector
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId ;
                      wm:riskTolerance ?riskTolerance .

            ?allocation rdf:type wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:sector ?sector ;
                        wm:allocationPct ?allocationPctRaw .
            FILTER(xsd:decimal(?allocationPctRaw) > 30) .

            ?health rdf:type wm:PortfolioHealth ;
                    wm:healthOfInvestor ?investor ;
                    wm:diversificationScore ?diversificationScoreRaw .
            FILTER(xsd:decimal(?diversificationScoreRaw) < 30) .
        }
    }
}
GROUP BY ?riskTolerance ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?shortfall)) - SUM(xsd:decimal(?holdingGain)) - SUM(xsd:decimal(?netCashFlow)) + SUM(xsd:decimal(?riskPressureScore)) AS ?score)
WHERE {
    {
        SELECT ?investorId (SUM(xsd:decimal(?shortfallRaw)) AS ?shortfall)
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:shortfall ?shortfallRaw .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
        WHERE {
            ?holding rdf:type wm:PortfolioHolding ;
                     wm:investorId ?investorId ;
                     wm:currentValue ?currentValue ;
                     wm:cost ?cost .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:investorId ?investorId ;
                      wm:amount ?amount .
        }
        GROUP BY ?investorId
    }
    {
        SELECT ?investorId (SUM(xsd:decimal(?riskScore)) AS ?riskPressureScore)
        WHERE {
            ?health rdf:type wm:PortfolioHealth ;
                    wm:investorId ?investorId ;
                    wm:riskScore ?riskScore .
        }
        GROUP BY ?investorId
    }
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?score) ASC(?investorId)
LIMIT 10

