PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
(AVG(xsd:decimal(?riskScore)) AS ?average_risk_score)
(AVG(xsd:decimal(?liquidityScore)) AS ?average_liquidity_score)
(AVG(xsd:decimal(?diversificationScore)) AS ?average_diversification_score)
(AVG(xsd:decimal(?goalMatchPct)) AS ?average_goal_match_pct)
WHERE {
  ?portfolioHealth rdf:type wm:PortfolioHealth ;
                  wm:riskScore ?riskScore ;
                  wm:liquidityScore ?liquidityScore ;
                  wm:diversificationScore ?diversificationScore ;
                  wm:goalMatchPct ?goalMatchPct .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COUNT(DISTINCT ?preAggregatedInvestor) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?sector
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?health .
      ?health rdf:type wm:PortfolioHealth ;
              wm:riskScore ?riskScoreRaw .
      FILTER(xsd:decimal(?riskScoreRaw) > 70) .
      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding ;
               wm:returnsPct ?returnsPctRaw ;
               wm:sector ?sector .
      FILTER(xsd:decimal(?returnsPctRaw) < 0) .
    }
    GROUP BY ?investorId ?sector
  }
  BIND(?investorId AS ?preAggregatedInvestor)
}
GROUP BY ?sector

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?diversificationScore ?allocationPct (COUNT(DISTINCT ?holding) AS ?pharmaHoldingCount)
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?health ;
            wm:hasSectorAllocation ?allocation ;
            wm:hasHolding ?holding .

  ?health wm:diversificationScore ?diversificationScoreRaw .
  BIND(xsd:decimal(?diversificationScoreRaw) AS ?diversificationScore)
  FILTER(?diversificationScore < 40)

  ?allocation wm:sector "Pharma" ;
              wm:allocationPct ?allocationPctRaw .
  BIND(xsd:decimal(?allocationPctRaw) AS ?allocationPct)
  FILTER(?allocationPct > 0)

  ?holding wm:sector "Pharma" .
}
GROUP BY ?investorId ?investorName ?diversificationScore ?allocationPct
HAVING (COUNT(DISTINCT ?holding) > 0)

PREFIX schema1: <http://schema.org/>

