            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  FILTER NOT EXISTS { ?investor wm:investmentGoal ?investmentGoal . }
  FILTER NOT EXISTS { ?investor wm:riskTolerance ?riskTolerance . }
  FILTER NOT EXISTS { ?investor wm:timeHorizon ?timeHorizon . }
  FILTER NOT EXISTS { ?investor wm:sectorFocus ?sectorFocus . }
  FILTER NOT EXISTS { ?investor wm:segment ?segment . }
  FILTER NOT EXISTS { ?investor wm:category ?category . }
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor ?investorId ?investorName
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorName ;
                wm:hasInvestmentGoal ?goal ;
                wm:hasRebalancingAction ?action ;
                wm:hasScenarioRebalancing ?scenario ;
                wm:hasCashFlow ?cashFlow .

      ?goal wm:investmentGoal ?goalType .
      FILTER(LCASE(STR(?goalType)) = "growth") .

      ?action wm:action ?actionType .
      FILTER(LCASE(STR(?actionType)) = "tactical") .

      ?scenario wm:scenario ?scenarioType .
      FILTER(LCASE(STR(?scenarioType)) = "bull market") .

      ?cashFlow wm:type ?cashFlowType ;
                wm:date ?date .
      FILTER(LCASE(STR(?cashFlowType)) = "tax refund") .
      FILTER(xsd:date(?date) > "2026-04-28"^^xsd:date) .
    }
    GROUP BY ?investor ?investorId ?investorName
  }
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
