SELECT ?sector (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?investorId ?sector (AVG(xsd:decimal(?diversificationScoreRaw)) AS ?diversificationScore)
    WHERE {
      ?health rdf:type wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:diversificationScore ?diversificationScoreRaw ;
              wm:investorId ?investorId .

      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:hasSector ?sectorObj ;
               wm:investorId ?investorId .
      ?sectorObj rdfs:label ?sector .
    }
    GROUP BY ?investorId ?sector
  }
}
GROUP BY ?sector

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?segment
    (SUM(?totalRebalancingAmount) AS ?totalRebalancingAmount)
    (SUM(?totalCashFlowAmount) AS ?totalCashFlowAmount)
    (SUM(?rebalancingTransactionCount) AS ?totalRebalancingTransactionCount)
    (SUM(?cashFlowTransactionCount) AS ?totalCashFlowTransactionCount)
WHERE {
    {
        SELECT
            ?investorId
            (COALESCE(?segmentRaw, "NULL") AS ?segment)
            (SUM(xsd:decimal(?raAmount)) AS ?totalRebalancingAmount)
            (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlowAmount)
            (COUNT(DISTINCT ?rebalanceId) AS ?rebalancingTransactionCount)
            (COUNT(DISTINCT ?cashFlowId) AS ?cashFlowTransactionCount)
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorId ?investorId .
            OPTIONAL { ?investor wm:segment ?segmentRaw . }

            {
                SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?raAmount) (?rebalanceId AS ?rebalanceId)
                WHERE {
                    ?rebalance rdf:type wm:RebalancingAction ;
                               wm:rebalancingActionOfInvestor ?investor ;
                               wm:amount ?amount ;
                               wm:rebalanceId ?rebalanceId .
                    ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId ?rebalanceId
            }

            {
                SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cfAmount) (?cashFlowId AS ?cashFlowId)
                WHERE {
                    ?cashFlow rdf:type wm:CashFlow ;
                              wm:cashFlowOfInvestor ?investor ;
                              wm:amount ?amount ;
                              wm:cashFlowId ?cashFlowId .
                    ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId ?cashFlowId
            }
        }
        GROUP BY ?investorId ?segmentRaw
    }
}
GROUP BY ?segment

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
