SELECT DISTINCT ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorName ?investorName ;
            wm:hasHolding ?holding .
  ?holding rdf:type wm:PortfolioHolding ;
           wm:category ?category .
  FILTER(NOT EXISTS {
    VALUES ?validCategory { "Equity" "Hybrid" "Gold" "Real Estate" "Debt" }
    FILTER(LCASE(STR(?category)) = LCASE(?validCategory))
  })
}

