SELECT ?investmentTypeLabel (COUNT(DISTINCT ?holding) AS ?holdingCount)
WHERE {
    {
        SELECT ?holding ?investmentType
        WHERE {
            ?holding rdf:type wm:PortfolioHolding .
            ?holding wm:hasInvestmentType ?investmentType .
        }
        GROUP BY ?holding ?investmentType
    }
    ?investmentType rdfs:label ?investmentTypeLabel .
}
