PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investmentGoal ?investmentGoal ;
              wm:riskTolerance ?riskTolerance ;
              wm:timeHorizon ?timeHorizon ;
              wm:sectorFocus ?sectorFocus ;
              wm:segment ?segment ;
              wm:category ?category .
    FILTER(
        ?investmentGoal != "" &&
        ?riskTolerance != "" &&
        ?timeHorizon != "" &&
        ?sectorFocus != "" &&
        ?segment != "" &&
        ?category != ""
    )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?riskTolerance
    (SUM(?netAmount) AS ?totalNetCashFlowAmount)
    (AVG(?scenarioChange) AS ?avgScenarioChange)
    (SUM(?scenarioCount) AS ?totalScenarioCount)
WHERE {
    {
        SELECT
            ?investor
            ?riskTolerance
            (SUM(xsd:decimal(?amount)) AS ?netAmount)
        WHERE {
            ?cashFlow rdf:type wm:CashFlow ;
                      wm:cashFlowOfInvestor ?investor ;
                      wm:amount ?amount .
            ?investor rdf:type wm:Investor ;
                      wm:riskTolerance ?riskToleranceRaw .
            BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)
        }
        GROUP BY ?investor ?riskTolerance
    }
    {
        SELECT
            ?investor
            ?riskTolerance
            (AVG(xsd:decimal(?change)) AS ?scenarioChange)
        WHERE {
            ?scenario rdf:type wm:ScenarioRebalancing ;
                      wm:scenarioRebalancingOfInvestor ?investor ;
                      wm:currentAllocationPct ?currentPct ;
                      wm:newAllocationPct ?newPct .
            ?investor rdf:type wm:Investor ;
                      wm:riskTolerance ?riskToleranceRaw .
            BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)
            BIND(xsd:decimal(?newPct) - xsd:decimal(?currentPct) AS ?change)
        }
        GROUP BY ?investor ?riskTolerance
    }
    {
        SELECT
            ?investor
            ?riskTolerance
            (COUNT(DISTINCT ?scenario) AS ?scenarioCount)
        WHERE {
            ?scenario rdf:type wm:ScenarioRebalancing ;
                      wm:scenarioRebalancingOfInvestor ?investor .
            ?investor rdf:type wm:Investor ;
                      wm:riskTolerance ?riskToleranceRaw .
            BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)
        }
        GROUP BY ?investor ?riskTolerance
    }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
