PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?holding ?holdingId ?investmentName
       ?investmentTypeLabel ?sectorLabel ?segmentLabel ?categoryLabel
WHERE {
  ?holding rdf:type wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:investmentName ?investmentName ;
           wm:hasInvestmentType ?investmentType ;
           wm:hasSector ?sector ;
           wm:hasSegment ?segment ;
           wm:hasCategory ?category .

  ?investmentType rdfs:label ?investmentTypeLabel .
  ?sector rdfs:label ?sectorLabel .
  ?segment rdfs:label ?segmentLabel .
  ?category rdfs:label ?categoryLabel .

  FILTER(?investmentTypeLabel != "" && ?sectorLabel != "" && ?segmentLabel != "" && ?categoryLabel != "")
}

PREFIX schema1: <http://schema.org/>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  ?riskScore_band
  (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidity_score)
  (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversification_score)
WHERE {
  {
    SELECT
      ?portfolioHealthId
      ?liquidityScore
      ?diversificationScore
      ?riskScore
      (SAMPLE(IF(xsd:decimal(?riskScore) < 3, "Low",
               IF(xsd:decimal(?riskScore) < 7, "Medium", "High"))) AS ?riskScore_band)
    WHERE {
      ?portfolioHealth rdf:type wm:PortfolioHealth ;
                      wm:portfolioHealthId ?portfolioHealthId ;
                      wm:liquidityScore ?liquidityScore ;
                      wm:diversificationScore ?diversificationScore ;
                      wm:riskScore ?riskScore .
    }
    GROUP BY ?portfolioHealthId ?liquidityScore ?diversificationScore ?riskScore
  }
}
GROUP BY ?riskScore_band

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    (COALESCE(?riskToleranceLabel, "NULL") AS ?riskToleranceGroup)
    (COALESCE(?goalTypeLabel, "NULL") AS ?goalType)
    (COUNT(DISTINCT ?preAggGoalId) AS ?goalCount)
WHERE {
    {
        SELECT ?goalId AS ?preAggGoalId ?riskToleranceLabel ?goalTypeLabel
        WHERE {
            ?goal rdf:type wm:InvestmentGoal ;
                  wm:goalId ?goalId ;
                  wm:belongsToInvestor ?investor ;
                  wm:hasInvestmentGoalType ?goalTypeNode .
            ?investor wm:hasRiskTolerance ?riskTolerance .
            ?riskTolerance rdfs:label ?riskToleranceLabel .
            ?goalTypeNode rdfs:label ?goalTypeLabel .
        }
        GROUP BY ?goalId ?riskToleranceLabel ?goalTypeLabel
    }
}
GROUP BY ?riskToleranceLabel ?goalTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName ?investorId
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasScenarioRebalancing ?scenarioRebalancing ;
            wm:hasInvestmentGoal ?goal .

  ?scenarioRebalancing rdf:type wm:ScenarioRebalancing ;
                       wm:scenario ?scenario .
  FILTER(LCASE(STR(?scenario)) = "bear market")

  ?goal rdf:type wm:InvestmentGoal ;
        wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 25)
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?holdingId ?investmentName ?sector
WHERE {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:holdingId ?holdingId ;
             wm:investmentName ?investmentName ;
             wm:hasSector ?sectorNode .

    ?sectorNode rdf:type wm:Sector ;
                wm:sector ?sectorRaw .

    BIND(LCASE(STR(?sectorRaw)) AS ?sector)

    FILTER NOT EXISTS {
        VALUES ?excludedSector {
            "technology" "financial services" "healthcare" "consumer goods"
            "real estate" "government" "corporate" "banking"
            "infrastructure" "private equity" "pharma" "automobile"
        }
        FILTER(LCASE(STR(?sectorRaw)) = ?excludedSector)
    }
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?riskScore
WHERE {
    {
        SELECT ?investor (MAX(xsd:decimal(?riskScoreRaw)) AS ?riskScore) ?investorName
        WHERE {
            ?investor rdf:type wm:Investor ;
                      wm:investorName ?investorName ;
                      wm:hasPortfolioHealth ?health .
            ?health wm:riskScore ?riskScoreRaw .
            {
                SELECT ?investor
                WHERE {
                    ?investor wm:hasHolding ?holding .
                    ?holding wm:currentValue ?currentValue ;
                             wm:cost ?cost ;
                             wm:returnsPct ?returnsPct .
                }
                GROUP BY ?investor
                HAVING (SUM(xsd:decimal(?returnsPct)) < 0)
            }
        }
        GROUP BY ?investor ?investorName
    }
}
ORDER BY DESC(?riskScore) ASC(?investorName)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(xsd:decimal(?preAggTimeToGoal)) AS ?avgTimeToGoalMonths)
       (AVG(xsd:decimal(?preAggProgress)) AS ?avgProgressPct)
WHERE {
  {
    SELECT ?investor
           (AVG(xsd:decimal(?timeToGoalMonths)) AS ?preAggTimeToGoal)
           (AVG(xsd:decimal(?progressPct)) AS ?preAggProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:timeToGoalMonths ?timeToGoalMonths ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  ?investor rdf:type wm:Investor ;
            wm:hasTimeHorizon ?timeHorizonObj .
  OPTIONAL { ?timeHorizonObj rdfs:label ?timeHorizonLabel . }
  BIND(COALESCE(STR(?timeHorizonLabel), "NULL") AS ?timeHorizon)
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avg_avg_sharpe_ratio)
       (AVG(xsd:decimal(?avgVolatilityPct)) AS ?avg_avg_volatility_pct)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio)
           (AVG(xsd:decimal(?volatility)) AS ?avgVolatilityPct)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?volatility ;
            wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
    ?investor rdf:type wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:hasCategory ?investorCategory .
    ?investorCategory rdfs:label "Debt" .

    FILTER NOT EXISTS {
        ?holding rdf:type wm:PortfolioHolding ;
                 wm:heldByInvestor ?investor ;
                 wm:hasCategory ?holdingCategory .
        ?holdingCategory rdfs:label "Debt" .
    }
}
